CAT = "nzfkAttach"; SEG = "ATT"
# Attachments and working platforms (NZQA skill standards 40736 and 40737).
Q = [
('Why does an operator trained only on bare forks need extra training for a clamp attachment?',
 'Each one handles differently', ['Clamps need an F endorsement', 'Clamps work only outdoors', "Clamps double the truck's capacity"],
 'Attachments change the operating parameters and hazards. Skill standard 40736 covers safe use of an attachment, and the PCBU must train operators on the attachments they use.'),
('A drum clamp is taken off the truck at the end of a job. What does skill standard 40736 expect next?',
 'Check the attachment and report faults', ['Leave it on the floor where it fell', 'Raise it on the forks overnight', 'Refit it to a different truck untested'],
 '40736 ends with removing the attachment, completing an attachment check and fault and hazard reporting.'),
('Which of these does skill standard 40736 NOT accept as an attachment for its assessment?',
 'Side shift', ['Drum clamp', 'Carton rotator', 'Jib arm'],
 '40736 says side shift devices and working platforms are not accepted as attachments for its assessment; clamps, rotators and jibs are.'),
('What three kinds of attachment does skill standard 40736 name?',
 'Fixed, removable, hydraulic', ['Steel, aluminium, timber', 'Small, medium, large', 'Front, side, rear-mounted'],
 "40736's indicative content lists permanently fixed, removable and hydraulically operated attachments."),
('A specialised quick-release hydraulic attachment arrives at the site. What does 40736 say the PCBU must provide?',
 'Specific training for it', ['Nothing beyond 40735', 'A new F endorsement', 'A second operator'],
 '40736 notes initial training may not cover specialised attachments, and the PCBU must train operators on the specialised attachments used at their workplace.'),
('Before using a newly fitted attachment, what must the operator check on the plates?',
 'Correct derated rating', ['Paint code of the attachment', "Maker's phone number", 'Date the truck was bought'],
 "40736 asks the operator to apply the correct load rating: the truck's derated capacity with that attachment, from the attachment and truck plates."),
('What must be checked when fitting a fork-mounted attachment?',
 'Secured as the maker specifies', ['It looks the right colour', 'It is lighter than the forks', 'It covers the load plate'],
 "Attachments must be securely fastened, following the manufacturer's instructions, so they cannot slide off or foul the mast when raised or lowered."),
('When is a forklift working platform used?',
 'Lifting people to work', ['Carrying pallets faster', 'Towing loaded trailers', 'Storing tools overnight'],
 '40737 defines a working platform as a cage attached to the forks to give temporary access to elevated places for personnel.'),
('Which prerequisite does skill standard 40737 add besides 40735?',
 'A safety harness standard', ['An F endorsement', 'A class 2 driver licence', 'A first aid certificate'],
 "40737 requires 40735 and unit standard 23229 'Use safety harness system when working at height', or an equivalent replacement."),
('What must a person in a forklift working platform wear?',
 'Harness and restraint lanyard', ['High-visibility vest only', 'Hard hat and gloves only', 'Ear muffs and boots only'],
 '40737 says a harness with a full restraint lanyard must be worn by personnel in the platform, attached to the correct anchor point.'),
('Where is the lanyard attached in a forklift working platform?',
 "Platform's anchor point", ['The mast lifting chain', 'The overhead guard bar', 'The top handrail'],
 '40737 requires the harness to be attached to the correct anchor point in the working platform.'),
('How should the mast and forks be set for every working platform raise?',
 'Mast vertical, forks centred', ['Mast tilted back, forks wide', 'Mast tilted forward, forks narrow', 'Mast vertical, side shifted'],
 "40737's evidence requires the mast to remain vertical and the forks centred for all raises."),
('What is done first before lifting a person in the working platform?',
 'Trial lift, nobody on', ['A lift at full speed', 'A lift with two people', 'A tilt test at height'],
 '40737 includes an initial trial lift and asks for raises with and without personnel on the platform.'),
('Which controls should be locked out on a forklift with a working platform where practical?',
 'Tilt controls', ['Horn and lights', 'Seat adjuster', 'Parking brake'],
 '40737 says the forklift tilt controls are locked out where practical, so the platform cannot be tilted with a person in it.'),
('What must the operator and the person in the platform keep up during the task?',
 'Communication throughout', ['Silence to concentrate', 'Hand signals only at the end', 'Radio only if it rains'],
 '40737 requires communication for the duration of the task between the operator and the person on the platform.'),
('What must be compared before a working platform is used?',
 'Platform load against capacity', ['Platform colour against the truck', 'Platform age against the battery', 'Platform height against the shift'],
 '40737 asks the operator to identify the safe working load of the platform in relation to the rated capacity of the forklift.'),
('What should the operator do with the truck while someone is up in a non-integrated platform?',
 'Stay at the controls, still', ['Drive slowly to the next bay', 'Leave to fetch their tools', 'Tilt the mast to help them reach'],
 'With a non-integrated platform the person aloft has no controls, so the operator stays at the controls and does not travel or tilt.'),
('What is an integrated working platform?',
 'Controls in the platform', ['Platform welded to the forks', 'Platform with no guardrails', 'Platform used only on roads'],
 'Integrated platforms have controls linked to the truck so only the person in the platform controls height and movement.'),
('What must also be planned before anyone works from a forklift platform?',
 'How to rescue them if needed', ['Which radio station to play', 'Lunch breaks for the operator', 'Where to park visitors'],
 '40737 lists emergency rescue procedures among the risks to plan for when operating a working platform.'),
('After a platform job, what does 40737 ask the operator to complete?',
 'Post-use check and fault report', ['Fitting a new load plate', 'A road test on the street', 'An F endorsement form'],
 '40737 ends with removing the platform, completing a post-operation check and fault and hazard reporting.'),
]
